class SwapSort
{
    String wrd, swapwrd, sortwrd;
    int len;

    SwapSort()
    {
        wrd = "";
        swapwrd = "";
        sortwrd = "";
        len = 0;
    }

    void readword()
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a word: ");
        wrd = sc.nextLine().toUpperCase();
        len = wrd.length();
    }

    void swapchar()
    {
        char first = wrd.charAt(0);
        char last = wrd.charAt(len - 1);
        swapwrd = last + wrd.substring(1, len - 1) + first;
    }

    void sortword()
    {
        char ch[] = wrd.toCharArray();
        for (int i = 0; i < len - 1; i++)
        {
            for (int j = 0; j < len - 1 - i; j++)
            {
                if (ch[j] > ch[j + 1])
                {
                    char t = ch[j];
                    ch[j] = ch[j + 1];
                    ch[j + 1] = t;
                }
            }
        }
        sortwrd = new String(ch);
    }

    void display()
    {
        System.out.println("Original word: " + wrd);
        System.out.println("Swapped word: " + swapwrd);
        System.out.println("Sorted word: " + sortwrd);
    }

    public static void main(String args[])
    {
        SwapSort ob = new SwapSort();
        ob.readword();
        ob.swapchar();
        ob.sortword();
        ob.display();
    }
}

