class BinSearch
{
    int arr[];
    int n;

    BinSearch(int nn)
    {
        n = nn;
        arr = new int[n];
    }

    void fillarray()
    {
        Scanner sc = new Scanner(System.in);
        for (int i = 0; i < n; i++)
        {
            System.out.print("Enter element: ");
            arr[i] = sc.nextInt();
        }
    }

    void sort()
    {
        for (int i = 0; i < n - 1; i++)
            for (int j = 0; j < n - 1 - i; j++)
                if (arr[j] > arr[j+1])
                {
                    int t = arr[j];
                    arr[j] = arr[j+1];
                    arr[j+1] = t;
                }
    }

    int bin_search(int l, int u, int v)
    {
        if (l > u)
            return -1;
        int mid = (l + u) / 2;
        if (arr[mid] == v)
            return mid;
        else if (v < arr[mid])
            return bin_search(l, mid - 1, v);
        else
            return bin_search(mid + 1, u, v);
    }

    public static void main(String args[])
    {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter size of array: ");
        int size = sc.nextInt();
        BinSearch ob = new BinSearch(size);
        ob.fillarray();
        ob.sort();
        System.out.print("Enter value to search: ");
        int v = sc.nextInt();
        int pos = ob.bin_search(0, size - 1, v);
        if (pos != -1)
            System.out.println("Found at index: " + pos);
        else
            System.out.println("Value not found.");
    }
}

