        len = wrd.length();
    }

    void mix_word(Mix P, Mix Q)
    {
        String result = "";
        int i = 0;
        int minLen = Math.min(P.len, Q.len);
        while (i < minLen)
        {
            result = result + P.wrd.charAt(i) + Q.wrd.charAt(i);
            i++;
        }
        if (P.len > minLen)
            result = result + P.wrd.substring(minLen);
        else if (Q.len > minLen)
            result = result + Q.wrd.substring(minLen);
        wrd = result;
        len = wrd.length();
    }

    void display()
    {
        System.out.println("Mixed word: " + wrd);
    }

    public static void main(String args[])
