            words[i] = st.nextToken();
            i++;
        }
        for (i = 0; i < n - 1; i++)
            for (int j = 0; j < n - 1 - i; j++)
                if (words[j].compareTo(words[j+1]) > 0)
                {
                    String t = words[j];
                    words[j] = words[j+1];
                    words[j+1] = t;
                }
        String result = "";
        for (i = 0; i < n; i++)
            result = result + words[i] + " ";
        sent = result.trim();
    }

    void display()
    {
        SortAlpha temp = new SortAlpha();
        temp.sent = this.sent;
        sort(temp);
        System.out.println("Original sentence: " + temp.sent);
        System.out.println("Sorted sentence: " + sent);
    }

    public static void main(String args[])
    {
        SortAlpha ob = new SortAlpha();
        ob.acceptsent();
        ob.display();
    }
}

